package com.datacleaning.app.controller;

import com.datacleaning.app.dto.CleaningRequest; import com.datacleaning.app.entity.CleaningJob; import com.datacleaning.app.repository.CleaningJobRepository; import com.datacleaning.app.service.DataService; import com.datacleaning.app.service.OllamaService;
import com.fasterxml.jackson.databind.ObjectMapper; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile;
import java.io.IOException; import java.util.*;

@RestController
public class DataController {
 private final DataService data; private final OllamaService ollama; private final CleaningJobRepository jobs; private final ObjectMapper mapper;
 public DataController(DataService data,OllamaService ollama,CleaningJobRepository jobs,ObjectMapper mapper){this.data=data;this.ollama=ollama;this.jobs=jobs;this.mapper=mapper;}
 @GetMapping("/health") public Map<String,Object> health(){return Map.of("status","ok","service","data-cleaning-api","ai","Ollama local");}
 @PostMapping(value="/upload",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public Map<String,Object> upload(@RequestParam("file") MultipartFile file)throws IOException {List<Map<String,Object>> rows=data.parse(file);String id=data.createSession(rows);jobs.save(new CleaningJob(id,Objects.requireNonNullElse(file.getOriginalFilename(),"dataset"),rows.size(),data.columns(rows).size()));return data.uploadResponse(id,Objects.requireNonNullElse(file.getOriginalFilename(),"dataset.csv"),rows);}
 @PostMapping("/generate-code") public Map<String,Object> generate(@Valid @RequestBody CleaningRequest request){List<Map<String,Object>> rows=data.rows(request.session_id());Map<String,String> schema=new LinkedHashMap<>();for(String c:data.columns(rows)){Object v=rows.stream().map(r->r.get(c)).filter(Objects::nonNull).findFirst().orElse("");schema.put(c,v.getClass().getSimpleName());}String plan=ollama.generatePlan(schema,rows.stream().limit(8).toList(),request.instruction());return Map.of("session_id",request.session_id(),"instruction",request.instruction(),"generated_code",plan,"message","Review the cleaning plan. Only approved operations are supported; arbitrary code is never executed.");}
 @PostMapping(value="/execute",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public Map<String,Object> execute(@RequestParam String session_id,@RequestParam String code,@RequestParam(defaultValue="json") String output_format)throws IOException {Map<String,Object> result=data.applyPlan(session_id,code);return result;}
 @PostMapping(value="/clean",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public ResponseEntity<?> quickClean(@RequestParam("file") MultipartFile file,@RequestParam(defaultValue="json") String output_format)throws IOException {List<Map<String,Object>> rows=data.parse(file);Map<String,Object> result=data.quickClean(rows);if("csv".equalsIgnoreCase(output_format)){byte[] csv=data.csvBytes((List<Map<String,Object>>)result.get("data"));return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=cleaned_data.csv").header("X-Total-Rows",String.valueOf(rows.size())).header("X-Processed",String.valueOf(rows.size())).header("X-Count",String.valueOf(result.get("count"))).contentType(MediaType.parseMediaType("text/csv")).body(csv);}return ResponseEntity.ok(result);}
 @GetMapping(value="/download/{session_id}",produces="text/csv") public ResponseEntity<byte[]> download(@PathVariable String session_id)throws IOException {byte[] csv=data.csvBytes(data.rows(session_id));return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=cleaned_data.csv").contentType(MediaType.parseMediaType("text/csv")).body(csv);}
 @DeleteMapping("/session/{session_id}") public Map<String,String> clear(@PathVariable String session_id){data.remove(session_id);jobs.deleteById(session_id);return Map.of("message","Session cleared");}
 @ExceptionHandler(NoSuchElementException.class) public ResponseEntity<Map<String,String>> notFound(Exception e){return ResponseEntity.status(404).body(Map.of("detail",e.getMessage()));}
 @ExceptionHandler({IllegalArgumentException.class,IllegalStateException.class}) public ResponseEntity<Map<String,String>> badRequest(Exception e){return ResponseEntity.badRequest().body(Map.of("detail",e.getMessage()));}
}
